from .round_div import round_div


def _parse_rate_to_fraction(rate_str: str) -> tuple[int, int]:
    """
    Parse a decimal rate string into a (numerator, denominator) pair of integers.
    E.g., "0.9132" -> (9132, 10000), "1" -> (1, 1), "1.5" -> (15, 10).
    """
    if "." in rate_str:
        integer_part, fractional_part = rate_str.split(".", 1)
        if integer_part == "" or integer_part == "-":
            if integer_part == "-":
                numerator = -int(fractional_part)
            else:
